const SpyTarget* nam_spy_target(const char* model)
{
  static const SpyTarget* const all[] = {&k_target_PB, &k_target_MX5, &k_target_GIG};
  for (size_t i = 0; i < sizeof(all) / sizeof(all[0]); ++i)
    if (model && strcmp(all[i]->model, model) == 0)
      return all[i];
  return NULL;
}
